use std::str::FromStr;

use midnight_did::did::MidnightDid;
use midnight_did::dlt::{ContractState, ContractStateDeserializer};
use serde_json::Value;

const DID: &str = "did:midnight:undeployed:02002faa3feaead86ae445622b5806ddd6da8e423992851b30a6f24b4aa8072a5c64";

const CONTRACT_STATES: [&str; 6] = [
    "",
    "",
    "",
    "",
    "",
    "",
];

#[test]
fn test_midnight_serde_rs() {
    use midnight_did_serde::DefaultContractStateDeserializer;

    let expected_did_doc = serde_json::from_str::<Vec<Value>>(include_str!("./did-documents.json")).unwrap();

    let deserializer = DefaultContractStateDeserializer;
    let did = MidnightDid::from_str(DID).unwrap();
    let did_docs = CONTRACT_STATES
        .iter()
        .map(|contract_state| {
            let state = ContractState::from_str(contract_state).unwrap();
            let (_, did_doc) = deserializer.deserialize(&did, &state).unwrap();
            let did_doc_json = serde_json::to_value(&did_doc).unwrap();
            did_doc_json
        })
        .collect::<Vec<_>>();

    assert_eq!(did_docs[0], expected_did_doc[0]);
    assert_eq!(did_docs[1], expected_did_doc[1]);
    assert_eq!(did_docs[2], expected_did_doc[2]);
    assert_eq!(did_docs[3], expected_did_doc[3]);
    assert_eq!(did_docs[4], expected_did_doc[4]);
    assert_eq!(did_docs[5], expected_did_doc[5]);
}
